// for con incremento
for (int i = 1; i < 4; i++) {
    System.out.println("Incrementando: " + i);
}
// for con decremento
for (int j = 3; j > 0; j--) {
    System.out.println("Decrementando: " + j);
}
// for infinito
for ( ; ; ) {
    System.out.println("Bucle infinito");
}

// while
int i = 1;
while (i < 3) {
    System.out.println("Iteración: " + i);
    i++;
}

// do while
int i = 1;
do {
    System.out.println("Iteración: " + i);
    i++;
} while (i < 1);

// break con etiquetas
W: while (true) {
    System.out.println("Dentro de W");
    X: while (true) {
        System.out.println("Dentro de X");
        break W;
    }
}
// continue con etiquetas
Y: while (true) {
    System.out.println("Dentro de Y");
    Z: while (true) {
        System.out.println("Dentro de Z");
        continue Y;
    }
}
